const cutoff = Date.now() - 26 * 3600 * 1000;
const strip = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;|&#39;/g, "'")
  .replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
return $input.all().map(i => i.json)
  .filter(j => j.link && j.title && new Date(j.isoDate || j.pubDate || 0).getTime() >= cutoff)
  .filter(j => !/\/(live|video|audio|gallery|ng-interactive|picture|membership|commentisfree)\//.test(j.link))
  .map(j => ({ json: { source: 'The Guardian', title: strip(j.title), link: j.link.split('?')[0], desc: strip(j.contentSnippet || j.content || '').slice(0, 200) } }));

const cutoff = Date.now() - 26 * 3600 * 1000;
const strip = s => String(s || '').replace(/<[^>]*>/g, ' ').replace(/&amp;/g, '&').replace(/&#x27;|&#39;/g, "'")
  .replace(/&quot;/g, '"').replace(/\s+/g, ' ').trim();
return $input.all().map(i => i.json)
  .filter(j => j.link && j.title && new Date(j.isoDate || j.pubDate || 0).getTime() >= cutoff)
  .filter(j => /\/news\/(articles|world)/.test(j.link))
  .map(j => ({ json: { source: 'BBC', title: strip(j.title), link: j.link.split('?')[0], desc: strip(j.contentSnippet || j.content || '').slice(0, 200) } }));

const md = $input.first().json.data;
if (typeof md !== 'string') return [];
const fmt = d => `${d.getUTCFullYear()}/${String(d.getUTCMonth() + 1).padStart(2, '0')}/${String(d.getUTCDate()).padStart(2, '0')}`;
const now = Date.now();
// CNN 網址的日期是美國時間：收 UTC 昨天、UTC 今天、台北今天
const days = new Set([fmt(new Date(now - 86400000)), fmt(new Date(now)), fmt(new Date(now + 8 * 3600000))]);
const exclude = /\/(live-news|videos?|interactive|gallery|audio)\//;
// 先記下每個連結對應的標題文字（若有）
const texts = {};
const tre = /\[([^\[\]]{15,300})\]\((https:\/\/(?:edition|www)\.cnn\.com\/\d{4}\/\d{2}\/\d{2}\/[^)\s#?]+)/g;
let t;
while ((t = tre.exec(md)) !== null) {
  if (!texts[t[2]] || t[1].length > texts[t[2]].length) texts[t[2]] = t[1].trim();
}
const slugTitle = link => {
  const seg = link.split('/').filter(Boolean).slice(-2)[0] || '';
  return decodeURIComponent(seg).replace(/-/g, ' ').replace(/^\w/, c => c.toUpperCase());
};
// 依在頁面上出現的順序（越前面通常越重要）
const re = /\]\((https:\/\/(?:edition|www)\.cnn\.com\/(\d{4}\/\d{2}\/\d{2})\/[^)\s#?]+)/g;
const seen = new Set();
const out = [];
let m;
while ((m = re.exec(md)) !== null) {
  const link = m[1];
  if (!days.has(m[2]) || exclude.test(link) || seen.has(link)) continue;
  seen.add(link);
  out.push({ json: { source: 'CNN', title: texts[link] || slugTitle(link), link, desc: '' } });
  if (out.length >= 20) break;
}
return out;

const MAX_PER_SOURCE = 40;
const seen = new Set(), count = {}, candidates = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.link || !j.title || seen.has(j.link)) continue;
  count[j.source] = count[j.source] || 0;
  if (count[j.source] >= MAX_PER_SOURCE) continue;
  seen.add(j.link);
  count[j.source]++;
  candidates.push({ id: candidates.length + 1, source: j.source, title: j.title, link: j.link, desc: j.desc || '' });
}
if (!candidates.length) return [];
const list = candidates.map(c => `${c.id} | ${c.source} | ${c.title}${c.desc ? ' | ' + c.desc : ''}`).join('\n');
return [{ json: { list, candidates } }];

const cands = $('Build Candidate List').first().json.candidates;
const SOURCES = ['The Guardian', 'BBC', 'CNN'];
const PICK = 6; // 每個來源取 6 則排名候選，之後抓全文失敗時由後面的補上
const first = $input.first()?.json || {};
const blocks = Array.isArray(first.content) ? first.content : [];
const raw = blocks.filter(b => b.type === 'text').map(b => b.text || '').join('\n');
let sel = {};
try {
  const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
  sel = JSON.parse(cleaned.slice(s, e + 1));
} catch (err) { sel = {}; }
const byId = new Map(cands.map(c => [c.id, c]));
const out = [];
for (const src of SOURCES) {
  const own = cands.filter(c => c.source === src);
  const picked = [];
  for (const id of (Array.isArray(sel[src]) ? sel[src] : [])) {
    const c = byId.get(Number(id));
    if (c && c.source === src && !picked.includes(c)) picked.push(c);
    if (picked.length >= PICK) break;
  }
  // 模型沒給夠（或呼叫失敗）時，用清單原本順序補滿
  for (const c of own) {
    if (picked.length >= PICK) break;
    if (!picked.includes(c)) picked.push(c);
  }
  picked.forEach((c, i) => out.push({ json: { source: c.source, title: c.title, link: c.link, rank: i + 1 } }));
}
return out;

const meta = $('Parse Selection').item.json;
const raw = $json.data;
if (typeof raw !== 'string' || !raw) return null;
const strip = s => s.replace(/<[^>]*>/g, ' ');
const dec = s => s.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/\s+/g, ' ').trim();
const grab = (seg, re, junk) => {
  const out = [];
  let m;
  while ((m = re.exec(seg)) !== null) {
    const t = dec(strip(m[1]));
    if (t && !(junk && junk.test(t))) out.push(t);
  }
  return out;
};
const pRe = () => /<p[^>]*>([\s\S]*?)<\/p>/g;
let title = meta.title, text = '';

if (meta.source === 'CNN') {
  // Jina Reader 回傳 JSON（title + content）；舊格式也相容
  let body = raw, t = '';
  try {
    const j = JSON.parse(raw);
    if (j && j.data) { t = j.data.title || ''; body = j.data.content || j.data.text || ''; }
  } catch (e) {
    const tm = raw.match(/^Title:\s*(.+)$/m);
    if (tm) t = tm[1];
    const cm = raw.match(/^\w+ Content:\s*$/m);
    body = cm ? raw.slice(raw.indexOf(cm[0]) + cm[0].length) : raw;
  }
  t = String(t).replace(/\s*\|\s*CNN.*$/i, '').trim();
  if (t) title = t;
  body = body.replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\[([^\]]+)\]\([^)]*\)/g, '$1');
  text = body.split('\n').map(l => l.trim())
    .filter(l => l.length >= 60 && !/^(#|\*|-|>|Image|Sign up|Read more|Watch|Copyright|©|Follow)/i.test(l)).join('\n');

} else if (meta.source === 'BBC') {
  const html = raw;
  const junk = /This video can not be played|To play this video/i;
  const art = (html.match(/<article[\s\S]*?<\/article>/i) || [html])[0];
  let paras = grab(art, /<p[^>]*class="[^"]*Paragraph[^"]*"[^>]*>([\s\S]*?)<\/p>/g, junk);
  if (paras.join('').length < 300) {
    paras = [];
    for (const part of html.split('data-component="text-block"').slice(1)) {
      paras.push(...grab(part.split(/data-component="/)[0], pRe(), junk));
    }
  }
  if (paras.join('').length < 300) paras = grab(art, pRe(), junk).filter(t => t.length >= 60);
  if (paras.join('').length < 300) paras = grab(html, pRe(), junk).filter(t => t.length >= 80);
  text = paras.join('\n');

} else {
  // The Guardian
  const html = raw;
  const junk = /^(Sign up|Follow |Read more|Related|Advertisement|Reuse this content|Share$|Topics$)/i;
  for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/g)) {
    try {
      const j = JSON.parse(m[1]);
      for (const o of (Array.isArray(j) ? j : [j])) {
        if (o && typeof o.articleBody === 'string' && o.articleBody.trim().length > text.length) text = o.articleBody.trim();
      }
    } catch (e) {}
  }
  if (text.length < 300) {
    let seg = '';
    const i = html.indexOf('data-gu-name="body"');
    if (i >= 0) seg = html.slice(i);
    else { const k = html.indexOf('id="maincontent"'); if (k >= 0) seg = html.slice(k); }
    const e = seg.indexOf('</article>');
    if (e > 0) seg = seg.slice(0, e);
    text = grab(seg, pRe(), junk).filter(t => t.length >= 40).join('\n');
  }
  if (text.length < 300) {
    const a = html.match(/<article[\s\S]*?<\/article>/i);
    if (a) text = grab(a[0], pRe(), junk).filter(t => t.length >= 60).join('\n');
  }
  if (text.length < 300) text = grab(html, pRe(), junk).filter(t => t.length >= 80).join('\n');
}
if (!text) return null;
return { source: meta.source, title, link: meta.link, text };

const MIN_LEN = 400, MAX_LEN = 4000, PER_SOURCE = 3, MAX_TOTAL = 9;
const seen = new Set();
const count = {};
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.text || j.text.length < MIN_LEN) continue;
  const key = String(j.title).toLowerCase().replace(/[^a-z0-9]/g, '');
  if (seen.has(key)) continue;
  count[j.source] = (count[j.source] || 0);
  if (count[j.source] >= PER_SOURCE) continue;
  seen.add(key);
  count[j.source]++;
  out.push({ json: { source: j.source, title: j.title, link: j.link, text: j.text.slice(0, MAX_LEN) } });
  if (out.length >= MAX_TOTAL) break;
}
return out;

