const src = $('Loop Over Items').item.json;
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = blocks.filter(b => b.type === 'text').map(b => b.text || '').join('\n')
  || $json.mergedResponse || $json.text || '';
let zhTitle = '', summary = '';
const cleaned = String(raw).trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const s = cleaned.indexOf('{'), e = cleaned.lastIndexOf('}');
try {
  const o = JSON.parse(s >= 0 && e > s ? cleaned.slice(s, e + 1) : cleaned);
  zhTitle = o.title || '';
  summary = o.summary || o.content || '';
} catch (err) {
  const t = cleaned.match(/"title"\s*:\s*"((?:[^"\\]|\\.)*)/);
  const m = cleaned.match(/"summary"\s*:\s*"((?:[^"\\]|\\.)*)/);
  zhTitle = t ? t[1] : '';
  summary = m ? m[1] : (t ? '' : cleaned);
}
summary = summary || '(簡介產生失敗，請點原文連結閱讀)';
// 英文標題若是網址就不顯示，避免網址重複出現
const enTitle = /^https?:\/\//i.test(src.title || '') ? '' : (src.title || '');
const link = SHOW_PREVIEW ? src.link : `<${src.link}>`;
const head = `📰 **【${src.source}】**\n### ${zhTitle || enTitle}\n` + (zhTitle && enTitle ? `-# ${enTitle}\n` : '');
const tail = `\n\n🔗 ${link}`;
const room = 1990 - head.length - tail.length - 1;
const body = summary.length > room ? summary.slice(0, room - 3) + '...' : summary;
return { discordMessage: `${head}\n${body}${tail}` };
